(deftest layouts-match-c-abi
  (doseq [[cname layout] layouts]
    (testing cname
      (let [{:keys [size offsets]} (get abi/structs cname)]
        (is (= size (ffi/layout-size layout)) (str cname " size"))
        (doseq [[field off] offsets]
          (is (= off (ffi/field-offset layout field)) (str cname "." (name field))))))))
